{"id":"gen-1792806931-7D5n3LgkYYs267XkKa9s","object":"chat.completion","created":1792806931,"model":"openai/gpt-6-luna","provider":"OpenAI","system_fingerprint":null,"service_tier":"default","choices":[{"index":0,"logprobs":null,"finish_reason":"stop","native_finish_reason":"completed","message":{"role":"assistant","content":"{
